<?php
/** Tabler card/list-group community layout, with clearly labelled design examples. */
use app\services\TeamUi;
use app\models\ForumThread;
$this->title='球迷论坛';
$boardCounts=(new yii\db\Query())->select(['category_id','n'=>new yii\db\Expression('COUNT(*)')])->from('forum_threads')->where(['status'=>'published'])->groupBy('category_id')->indexBy('category_id')->all();
$main=Yii::$app->user->identity?->profile?->mainTeam;
$recent=ForumThread::find()->with('team')->where(['status'=>'published','is_pinned'=>0])->orderBy(['last_activity_at'=>SORT_DESC])->limit(3)->all();
?>
<?= $this->render('/catalog/_masthead',['heading'=>'球迷论坛','photo'=>'bc-place','photoLabel'=>'温哥华卑诗体育场','class'=>'forum-cover']) ?>
<div class="community-scope">
<header class="community-heading"><div><h2>讨论区</h2></div><a class="button" href="/forum/new">＋ 发布主题</a></header>
<nav class="board-cards" aria-label="讨论板块"><a class="board-card <?= !Yii::$app->request->get('category')?'is-current':'' ?>" href="/forum"><span class="board-glyph">◎</span><div><strong>全部板块</strong><small><?= array_sum(array_column($boardCounts,'n')) ?> 个主题</small></div><span>↗</span></a><?php foreach($categories as $i=>$c): ?><a class="board-card <?= Yii::$app->request->get('category')==$c->id?'is-current':'' ?>" href="/forum?category=<?= (int)$c->id ?>"><span class="board-glyph"><?= ['⚑','▥','◇','▧'][$i%4] ?></span><div><strong><?= e($c->name) ?></strong><small><?= (int)($boardCounts[$c->id]['n']??0) ?> 个主题</small></div><span>↗</span></a><?php endforeach ?></nav>
<div class="community-columns"><section class="card topic-panel"><div class="card-header topic-panel-head"><nav class="topic-tabs" aria-label="主题列表"><a href="/forum" class="<?= !Yii::$app->request->get('feed')&&!Yii::$app->request->get('mine')?'active':'' ?>">最新讨论</a><a href="/forum?feed=main" class="<?= Yii::$app->request->get('feed')==='main'?'active':'' ?>">我的主队</a><a href="/forum?mine=1" class="<?= Yii::$app->request->get('mine')==='1'?'active':'' ?>">我的主题</a></nav><span class="topic-total"><?= (int)$provider->totalCount ?> 个主题</span></div>
<form method="get" class="topic-search"><label><span class="visually-hidden">搜索讨论</span><input name="q" value="<?= e(Yii::$app->request->get('q','')) ?>" placeholder="搜索讨论标题"></label><?php foreach(['category','feed','mine'] as $key): ?><?php if(Yii::$app->request->get($key)): ?><input type="hidden" name="<?= e($key) ?>" value="<?= e(Yii::$app->request->get($key)) ?>"><?php endif ?><?php endforeach ?><label><span class="visually-hidden">球队</span><select name="team_id" data-team-select><option value="">全部球队</option><?php foreach($teams as $t): ?><option value="<?= (int)$t->id ?>" data-flag="<?= e(TeamUi::url($t)) ?>" <?= Yii::$app->request->get('team_id')==$t->id?'selected':'' ?>><?= e($t->name) ?></option><?php endforeach ?></select></label><button type="submit" aria-label="搜索讨论">搜索</button></form>
<div class="list-group list-group-flush community-topic-list"><?php foreach($provider->models as $t): ?><article class="list-group-item topic-item <?= $t->is_pinned?'topic-pinned':'' ?>"><span class="avatar topic-avatar tone-<?= (int)$t->category_id%4 ?>" aria-hidden="true"><?= $t->team?TeamUi::flag($t->team):'聊' ?></span><div class="topic-copy"><div class="topic-labels"><span class="topic-board"><?= e($t->category?->name) ?></span><?php if($t->is_pinned): ?><b class="topic-pill">置顶</b><?php endif ?><?php if($t->isDemo): ?><b class="topic-pill demo-pill">示例帖</b><?php endif ?><?php if($t->is_locked): ?><span class="topic-pill">已锁定</span><?php endif ?></div><h3><a href="/forum/<?= (int)$t->id ?>"><?= e($t->displayTitle) ?></a></h3><p><?= e(mb_substr($t->body,0,95)) ?></p><div class="topic-meta"><span><?= e($t->author?->displayName??'球迷') ?></span><span>·</span><time><?= e(date('m月d日 H:i',strtotime($t->last_activity_at))) ?></time><?php if($t->team): ?><a href="/forum?team_id=<?= (int)$t->team_id ?>"><?= TeamUi::label($t->team) ?></a><?php endif ?></div></div><div class="topic-count"><b><?= (int)$t->reply_count ?></b><span>回复</span><small>♡ <?= (int)$t->like_count ?></small></div></article><?php endforeach ?></div>
<?php if(!$provider->models): ?><div class="community-empty"><span>◇</span><h3>还没有相关讨论</h3><a href="/forum/new">发布第一个主题 ↗</a></div><?php endif ?><div class="card-footer"><?= yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?></div></section>
<aside class="community-aside"><section class="card main-team-panel"><div class="card-body"><span class="community-eyebrow">我的主队</span><?php if($main): ?><h3><?= TeamUi::label($main) ?></h3><a href="/forum?team_id=<?= (int)$main->id ?>">进入球队看台 ↗</a><?php else: ?><h3>支持哪支球队？</h3><div class="support-flags"><?php foreach(array_slice($teams,0,6) as $t): ?><?= TeamUi::flag($t) ?><?php endforeach ?></div><?php endif ?><a href="/profile" class="button"><?= $main?'管理我的主队':'选择我的主队' ?></a></div></section><section class="card aside-topics"><div class="card-header"><h3>最新主题</h3></div><div class="list-group list-group-flush"><?php foreach($recent as $i=>$t): ?><a class="list-group-item" href="/forum/<?= (int)$t->id ?>"><span class="aside-rank">0<?= $i+1 ?></span><div><b><?= e($t->displayTitle) ?></b><small><?= $t->isDemo?'示例帖':e($t->category?->name) ?></small></div></a><?php endforeach ?></div></section><details class="card community-rules"><summary>版规</summary><p>围绕比赛交流，尊重不同观点。请勿刷屏、辱骂或发布广告。</p></details></aside></div></div>
